/* rd_asm.S: reedie's sample loops (rd_fast.h rd_loop: settled, start-up, release) in Blackfin assembly, bit for bit.
 * Generated by gen_asm.py (edit that, not this file).
 * void rd_k_<variant>(rd_ak_t *k, int count): R0 = k (rd_fast.h rd_ak_t: ring pointers, packed constants, state),
 * R1 = count >= 1. The C (rd_loop) is the spec and the host path; the hundekraft kennel port harness/rd_asm_cmp.py compares the two on bcore.
 *
 * Ranges the 16-bit multiplies rest on (rd_fast.h rd_asm_run checks the incoming state, the rest is by construction):
 *  - the two taps: a = a0 + ((pa - a0) fr >> 15) = (a0 (32767 - fr) + pa fr + a0) >> 15, a blend of two int16, so int16;
 *  - r = (c1 a - c b) >> 15 = (a (32767 - c) + a - c b) >> 15, within int16 for int16 a, b;
 *  - lp, dc: lp + ((r - lp) k >> 15) = (lp (32768 - k) + r k) >> 15 with 0 < k < 32768: stays between lp and r;
 *  - chat: (chat 32548 + |nz| 220) >> 15 in 0..32767 (|nz| up to 32768: the product's absolute value in A0);
 *  - b1: (b1 31834 + nz 934) >> 15, int16; x clamped to +-32767, x2, x3 and x - x3 int16; u0 < 32768 (rest <= 10853);
 *  - r after the DC blocker, b2, op, u, col, airq and the output are 17 bits or more: 32-bit ops (*= for products).
 * Fraction-mode products are doubled and a (T) half extraction takes bits 31..16: floor(sum / 32768). No operand
 * pair is -32768 x -32768 (every constant is >= 0, x is clamped to +-32767, chat >= 0).
 * Copyright (C) 2026 Hundekraft. Derived from reedie.c, Copyright (C) 2026 nvmsocool.
 * GPL-3.0-or-later with the OP-1 firmware permission (see LICENSE and NOTICE). */
#ifdef __bfin__                 /* the host builds use the C */

/* rd_ak_t offsets (rd_fast.h pins them) */
#define K_FRC     0      /* H 32767 - fr2, L 32767 - fr */
#define K_FR      4      /* H fr2, L fr */
#define K_ONE     8      /* 0x00010001 */
#define K_C       12      /* H c, L 32767 - c */
#define K_LD      16      /* H 32768 - alpha, L 32768 - aloss */
#define K_AL      20      /* H alpha, L aloss */
#define K_G       24      /* L 32760 */
#define K_CH      28      /* H 220, L 32548 */
#define K_B1      32      /* H 934, L 31834 */
#define K_BZ      36      /* H 16384, L buzz */
#define K_WP      40      /* H 8192 */
#define K_WN      44      /* H -8192 */
#define K_REST    48
#define K_P32767  52
#define K_M32767  56
#define K_UA      60      /* H u0, L amp */
#define K_8192    64      /* L 8192 */
#define K_14238   68
#define K_EX      72      /* ex_hi6 */
#define K_11468   76
#define K_BREATH  80
#define K_VGAIN   84
#define K_P12000  88
#define K_M12000  92
#define K_P28000  96
#define K_M28000  100
#define K_6400    104
#define K_TILT    108
#define K_GAIN    112
#define K_3       116
#define K_RNG     120
#define K_LPDC    124      /* H dc, L lp */
#define K_B1CH    128      /* H b1, L chat */
#define K_B2      132
#define K_OP      136
#define K_BR      140      /* 32767 - 3 (age - 1): decremented before use */
#define K_ZERO    144
#define K_FQ      148      /* age fstep (fill) */
#define K_FSTEP   152
#define K_AQ      156      /* (1500 - age) astep (attack blow) */
#define K_ASTEP   160
#define K_RQ      164      /* age rstep (reed ramp) or rel relstep (release) */
#define K_RSTEP   168
#define K_SQ      172      /* (seeddur - (age - ramplen)) sstep (chiff) */
#define K_SSTEP   176
#define K_RING    180
#define K_PA      184
#define K_PB      188
#define K_W       192
#define K_OUT     196

/* Each loop: P1 = k, P3 = k + 64, P4 = k + 128, P0 = out, I0 = pa (then a0), I1 = pb (then b0), I2 = write, all
 * three on the ring (circular, 8192 bytes). Kept: R7 = rng, R6 = (dc : lp), R5 = (b1 : chat); b2, op, the breath
 * ramp and the start-up sums in k. */
.text
	.balign 32
	.global _rd_k_set
	.type _rd_k_set, STT_FUNC
/* rd_k_set(k, count): F 0 A 0 R 0 S 0 L 0 Z 0 (body()); 100 packets a sample */
_rd_k_set:
	[--SP] = (R7:4, P5:3);
	P1 = R0;
	P2 = R1;
	R2 = 64;
	R2 = R0 + R2;
	P3 = R2;
	R2 = 128;
	R2 = R0 + R2;
	P4 = R2;
	R0 = [P1 + K_RING];
	B0 = R0;
	B1 = R0;
	B2 = R0;
	R1 = 8192;
	L0 = R1;
	L1 = R1;
	L2 = R1;
	R0 = [P1 + K_PA];
	I0 = R0;
	R0 = [P1 + K_PB];
	I1 = R0;
	R0 = [P1 + K_W];
	I2 = R0;
	P0 = [P1 + K_OUT];
	R7 = [P1 + K_RNG];
	R6 = [P1 + K_LPDC];
	R5 = [P1 + K_B1CH];
	LSETUP (.Lset_b, .Lset_e) LC0 = P2;
.Lset_b:
	/* noise: rng ^= rng << 13; ^= >> 17; ^= << 5; nz = rng.H */
	R1 = R7 << 13;
	R7 = R7 ^ R1;
	R1 = R7 >> 17 || R3 = [P1 + 32] || NOP;
	R7 = R7 ^ R1;
	R1 = R7 << 5 || R2 = [P1 + 28] || NOP;
	R7 = R7 ^ R1;
	/* chat = (chat 32548 + |nz| 220) >> 15; b1 = (b1 31834 + nz 934) >> 15 */
	A0 = R7.H * R2.H;
	A0 = ABS A0;
	R5.L = (A0 += R5.L * R2.L) (T);
	A1 = R5.H * R3.L || R4 = [P1 + 8] || NOP;
	R5.H = (A1 += R7.H * R3.H) (T) || R0.L = W[I0++] || R2 = [P1 + 0];
	/* the two taps: R0 = (pb : pa), R1 = (b0 : a0) -> R0 = (b : a) */
	MNOP || R1.L = W[I0] || NOP;
	MNOP || R0.H = W[I1++] || NOP;
	MNOP || R1.H = W[I1] || NOP;
	MNOP || R3 = [P1 + 4] || NOP;
	A1 = R1.H * R2.H, A0 = R1.L * R2.L;
	A1 += R0.H * R3.H, A0 += R0.L * R3.L;
	R0.H = (A1 += R1.H * R4.H), R0.L = (A0 += R1.L * R4.L) (T) || R2 = [P1 + 12] || NOP;
	/* r = (c1 a - c b) >> 15 */
	A0 = R0.L * R2.L;
	A0 += R0.L * R4.L;
	R1.L = (A0 -= R0.H * R2.H) (T) || R3 = [P1 + 16] || NOP;
	/* lp, dc */
	MNOP || R2 = [P1 + 20] || NOP;
	A1 = R6.H * R3.H, A0 = R6.L * R3.L;
	R6.L = (A0 += R1.L * R2.L) (T);
	R6.H = (A1 += R6.L * R2.H) (T) || R3 = [P1 + 24] || NOP;
	/* r = ((lp - dc) 32760) >> 15, 32 bits: R0 */
	A0 = R6.L * R3.L (IS);
	R0 = (A0 -= R6.H * R3.L) (IS);
	R0 = R0 >>> 15 || R1 = [P4 + 8] || NOP;
	/* op += ((r - op) 6400) >> 15; col = r + ((tilt (r - op)) >> 15); Y = (col gain) >> 15: R2 */
	R2 = R0 - R1 (NS) || R3 = [P3 + 40] || NOP;
	R2 *= R3;
	R2 = R2 >>> 15;
	R1 = R1 + R2 (NS);
	R2 = R0 - R1 (NS) || R3 = [P3 + 44] || NOP;
	R2 *= R3;
	R2 = R2 >>> 15 || [P4 + 8] = R1 || NOP;
	R2 = R2 + R0 (NS) || R3 = [P3 + 48] || NOP;
	R2 *= R3;
	R2 = R2 >>> 15 || R3 = [P1 + 36] || NOP;
	/* wob = clamp(((chat - 16384) buzz) >> 15, +-8192), in R1.H */
	A1 = R5.L * R3.L || R4 = [P1 + 40] || NOP;
	R1.H = (A1 -= R3.H * R3.L) (T) || R3 = [P1 + 44] || NOP;
	R1 = MAX(R1, R3) (V);
	R1 = MIN(R1, R4) (V) || R3 = [P1 + 48] || NOP;
	/* x = clamp(rest - r + (wob >> 3), +-32767): R3 */
	R3 = R3 - R0 (NS);
	R4 = R1 >>> 19 || R0 = [P1 + 56] || NOP;
	R3 = R3 + R4 (NS) || R4 = [P1 + 52] || NOP;
	R3 = MIN(R3, R4);
	R3 = MAX(R3, R0);
	/* in = (wob >> 2) + (nz >> 10): R1 */
	R1 = R1 >>> 18;
	R4 = R7 >>> 26;
	R1 = R1 + R4 (NS);
	/* x2 = x x >> 15, x3 = x2 x >> 15, dx = x - x3: R0.L */
	R0.L = R3.L * R3.L (T);
	R0.H = R0.L * R3.L (T);
	R0.L = R3.L - R0.H (NS) || R4 = [P1 + 60] || NOP;
	/* u = (dx amp >> 13) - u0 = (dx amp - u0 8192) >> 13; u = (u 32767) >> 15; in += u */
	MNOP || R3 = [P3 + 0] || NOP;
	A0 = R0.L * R4.L (IS);
	R0 = (A0 -= R4.H * R3.L) (IS);
	R0 = R0 >>> 13 || R3 = [P1 + 52] || NOP;
	R0 *= R3;
	R0 = R0 >>> 15;
	R1 = R1 + R0 (NS) || R3 = [P1 + 36] || NOP;
	/* rasp = (((nz chat) >> 15) buzz) >> 15; in += rasp */
	R0.L = R7.H * R5.L (T);
	R0.L = R0.L * R3.L (T);
	R0 = R0.L (X);
	R1 = R1 + R0 (NS);
	/* b2 += ((nz - b1 - b2) 14238) >> 15: R4 */
	R0 = R7 >>> 16;
	R3 = R5 >>> 16;
	R0 = R0 - R3 (NS) || R4 = [P4 + 4] || NOP;
	R0 = R0 - R4 (NS) || R3 = [P3 + 4] || NOP;
	R0 *= R3;
	R0 = R0 >>> 15;
	R4 = R4 + R0 (NS) || R0 = [P3 + 8] || NOP;
	/* Y += (ex_hi6 b2) >> 15 */
	R0 *= R4;
	R0 = R0 >>> 15 || R3 = [P3 + 52] || NOP;
	R2 = R2 + R0 (NS) || R0 = [P4 + 12] || NOP;
	/* airq = clamp((((((b2 bamp) >> 15) breath) >> 14) vgain) >> 15, +-12000): R0 */
	R0 = R0 - R3 (NS) || R3 = [P3 + 12] || NOP;
	MNOP || [P4 + 12] = R0 || NOP;
	R0 = MAX(R0, R3) || [P4 + 4] = R4 || NOP;
	R0 *= R4;
	R0 = R0 >>> 15 || R3 = [P3 + 16] || NOP;
	R0 *= R3;
	R0 = R0 >>> 14 || R3 = [P3 + 20] || NOP;
	R0 *= R3;
	R0 = R0 >>> 15 || R3 = [P3 + 24] || NOP;
	MNOP || R4 = [P3 + 28] || NOP;
	R0 = MIN(R0, R3);
	R0 = MAX(R0, R4);
	/* ring[wp] = sat16(in + (airq >> 1)) */
	R3 = R0 >>> 1;
	R1 = R1 + R3 (NS);
	R1 = R1 << 16 (S);
	/* y = Y + airq + (airq >> 2), rounded above 28000, clamped to +-32767 */
	R2 = R2 + R0 (NS) || W[I2++] = R1.H || NOP;
	R0 = R0 >>> 2 || R4 = [P3 + 32] || NOP;
	R2 = R2 + R0 (NS) || R3 = [P3 + 36] || NOP;
	R0 = MAX(R2, R3);
	R0 = MIN(R0, R4);
	R2 = R2 - R0 (NS);
	R2 = R2 >>> 3 || R4 = [P1 + 52] || NOP;
	R2 = R2 + R0 (NS) || R3 = [P1 + 56] || NOP;
	R2 = MAX(R2, R3);
	R2 = MIN(R2, R4);
.Lset_e:
	MNOP || W[P0++] = R2 || NOP;
	[P1 + K_RNG] = R7;
	[P1 + K_LPDC] = R6;
	[P1 + K_B1CH] = R5;
	R0 = I2;
	[P1 + K_W] = R0;
	R0 = 0;
	L0 = R0;
	L1 = R0;
	L2 = R0;
	(R7:4, P5:3) = [SP++];
	RTS;
	.size _rd_k_set, .-_rd_k_set

	.balign 32
	.global _rd_k_fr
	.type _rd_k_fr, STT_FUNC
/* rd_k_fr(k, count): F 1 A 1 R 1 S 0 L 0 Z 0 (body()); 111 packets a sample */
_rd_k_fr:
	[--SP] = (R7:4, P5:3);
	P1 = R0;
	P2 = R1;
	R2 = 64;
	R2 = R0 + R2;
	P3 = R2;
	R2 = 128;
	R2 = R0 + R2;
	P4 = R2;
	R0 = [P1 + K_RING];
	B0 = R0;
	B1 = R0;
	B2 = R0;
	R1 = 8192;
	L0 = R1;
	L1 = R1;
	L2 = R1;
	R0 = [P1 + K_PA];
	I0 = R0;
	R0 = [P1 + K_PB];
	I1 = R0;
	R0 = [P1 + K_W];
	I2 = R0;
	P0 = [P1 + K_OUT];
	R7 = [P1 + K_RNG];
	R6 = [P1 + K_LPDC];
	R5 = [P1 + K_B1CH];
	LSETUP (.Lfr_b, .Lfr_e) LC0 = P2;
.Lfr_b:
	/* noise: rng ^= rng << 13; ^= >> 17; ^= << 5; nz = rng.H */
	R1 = R7 << 13;
	R7 = R7 ^ R1;
	R1 = R7 >> 17 || R3 = [P1 + 32] || NOP;
	R7 = R7 ^ R1;
	R1 = R7 << 5 || R2 = [P1 + 28] || NOP;
	R7 = R7 ^ R1;
	/* chat = (chat 32548 + |nz| 220) >> 15; b1 = (b1 31834 + nz 934) >> 15 */
	A0 = R7.H * R2.H;
	A0 = ABS A0;
	R5.L = (A0 += R5.L * R2.L) (T);
	A1 = R5.H * R3.L || R4 = [P1 + 8] || NOP;
	R5.H = (A1 += R7.H * R3.H) (T) || R0.L = W[I0++] || R2 = [P1 + 0];
	/* the two taps: R0 = (pb : pa), R1 = (b0 : a0) -> R0 = (b : a) */
	MNOP || R1.L = W[I0] || NOP;
	MNOP || R0.H = W[I1++] || NOP;
	MNOP || R1.H = W[I1] || NOP;
	MNOP || R3 = [P1 + 4] || NOP;
	A1 = R1.H * R2.H, A0 = R1.L * R2.L;
	A1 += R0.H * R3.H, A0 += R0.L * R3.L;
	R0.H = (A1 += R1.H * R4.H), R0.L = (A0 += R1.L * R4.L) (T) || R2 = [P1 + 12] || NOP;
	/* r = (c1 a - c b) >> 15 */
	A0 = R0.L * R2.L;
	A0 += R0.L * R4.L;
	R1.L = (A0 -= R0.H * R2.H) (T) || R3 = [P4 + 20] || NOP;
	/* fill: r = (r fq) >> 15 (fq = age fstep < 32767 while age < di); fq += fstep */
	R1.L = R1.L * R3.L (T) || R2 = [P4 + 24] || NOP;
	R3 = R3 + R2 (NS) || R2 = [P1 + 20] || NOP;
	MNOP || [P4 + 20] = R3 || NOP;
	/* lp, dc */
	MNOP || R3 = [P1 + 16] || NOP;
	A1 = R6.H * R3.H, A0 = R6.L * R3.L;
	R6.L = (A0 += R1.L * R2.L) (T);
	R6.H = (A1 += R6.L * R2.H) (T) || R3 = [P1 + 24] || NOP;
	/* r = ((lp - dc) 32760) >> 15, 32 bits: R0 */
	A0 = R6.L * R3.L (IS);
	R0 = (A0 -= R6.H * R3.L) (IS);
	R0 = R0 >>> 15 || R1 = [P4 + 8] || NOP;
	/* op += ((r - op) 6400) >> 15; col = r + ((tilt (r - op)) >> 15); Y = (col gain) >> 15: R2 */
	R2 = R0 - R1 (NS) || R3 = [P3 + 40] || NOP;
	R2 *= R3;
	R2 = R2 >>> 15;
	R1 = R1 + R2 (NS);
	R2 = R0 - R1 (NS) || R3 = [P3 + 44] || NOP;
	R2 *= R3;
	R2 = R2 >>> 15 || [P4 + 8] = R1 || NOP;
	R2 = R2 + R0 (NS) || R3 = [P3 + 48] || NOP;
	R2 *= R3;
	R2 = R2 >>> 15 || R3 = [P1 + 36] || NOP;
	/* wob = clamp(((chat - 16384) buzz) >> 15, +-8192), in R1.H */
	A1 = R5.L * R3.L || R4 = [P1 + 40] || NOP;
	R1.H = (A1 -= R3.H * R3.L) (T) || R3 = [P1 + 44] || NOP;
	R1 = MAX(R1, R3) (V);
	R1 = MIN(R1, R4) (V) || R3 = [P1 + 48] || NOP;
	/* x = clamp(rest - r + (wob >> 3), +-32767): R3 */
	R3 = R3 - R0 (NS);
	R4 = R1 >>> 19 || R0 = [P1 + 56] || NOP;
	R3 = R3 + R4 (NS) || R4 = [P1 + 52] || NOP;
	R3 = MIN(R3, R4);
	R3 = MAX(R3, R0);
	/* in = (wob >> 2) + (nz >> 10): R1 */
	R1 = R1 >>> 18;
	R4 = R7 >>> 26;
	R1 = R1 + R4 (NS);
	/* x2 = x x >> 15, x3 = x2 x >> 15, dx = x - x3: R0.L */
	R0.L = R3.L * R3.L (T);
	R0.H = R0.L * R3.L (T) || R4 = [P4 + 32] || NOP;
	R0.L = R3.L - R0.H (NS) || R3 = [P4 + 28] || NOP;
	/* u = (dx amp >> 13) - u0 = (dx amp - u0 8192) >> 13; u = (u 32767) >> 15; in += u */
	/* attack blow: amp + ((amp max(aq >> 15, 0)) >> 15) (aq = (1500 - age) astep, >= -6.3e8 in the start-up); aq -= astep */
	R4 = R3 - R4 (NS);
	MNOP || [P4 + 28] = R4 || NOP;
	R3 = R3 >>> 15 || R4 = [P4 + 16] || NOP;
	R3 = MAX(R3, R4);
	MNOP || R4 = [P1 + 60] || NOP;
	R3.L = R4.L * R3.L (T);
	R3.L = R3.L + R4.L (NS);
	A0 = R0.L * R3.L (IS) || R3 = [P3 + 0] || NOP;
	R0 = (A0 -= R4.H * R3.L) (IS) || R4 = [P4 + 40] || NOP;
	R0 = R0 >>> 13 || R3 = [P4 + 36] || NOP;
	/* reed ramp: reed = rq >> 15 (rq = age rstep, age < ramplen) */
	R4 = R3 + R4 (NS);
	R3 = R3 >>> 15 || [P4 + 36] = R4 || NOP;
	R0 *= R3;
	R0 = R0 >>> 15;
	R1 = R1 + R0 (NS) || R3 = [P1 + 36] || NOP;
	/* rasp = (((nz chat) >> 15) buzz) >> 15; in += rasp */
	R0.L = R7.H * R5.L (T);
	R0.L = R0.L * R3.L (T);
	R0 = R0.L (X);
	R1 = R1 + R0 (NS);
	/* b2 += ((nz - b1 - b2) 14238) >> 15: R4 */
	R0 = R7 >>> 16;
	R3 = R5 >>> 16;
	R0 = R0 - R3 (NS) || R4 = [P4 + 4] || NOP;
	R0 = R0 - R4 (NS) || R3 = [P3 + 4] || NOP;
	R0 *= R3;
	R0 = R0 >>> 15;
	R4 = R4 + R0 (NS) || R0 = [P3 + 8] || NOP;
	/* Y += (ex_hi6 b2) >> 15 */
	R0 *= R4;
	R0 = R0 >>> 15 || R3 = [P3 + 52] || NOP;
	R2 = R2 + R0 (NS) || R0 = [P4 + 12] || NOP;
	/* airq = clamp((((((b2 bamp) >> 15) breath) >> 14) vgain) >> 15, +-12000): R0 */
	R0 = R0 - R3 (NS) || R3 = [P3 + 12] || NOP;
	MNOP || [P4 + 12] = R0 || NOP;
	R0 = MAX(R0, R3) || [P4 + 4] = R4 || NOP;
	R0 *= R4;
	R0 = R0 >>> 15 || R3 = [P3 + 16] || NOP;
	R0 *= R3;
	R0 = R0 >>> 14 || R3 = [P3 + 20] || NOP;
	R0 *= R3;
	R0 = R0 >>> 15 || R3 = [P3 + 24] || NOP;
	MNOP || R4 = [P3 + 28] || NOP;
	R0 = MIN(R0, R3);
	R0 = MAX(R0, R4);
	/* ring[wp] = sat16(in + (airq >> 1)) */
	R3 = R0 >>> 1;
	R1 = R1 + R3 (NS);
	R1 = R1 << 16 (S);
	/* y = Y + airq + (airq >> 2), rounded above 28000, clamped to +-32767 */
	R2 = R2 + R0 (NS) || W[I2++] = R1.H || NOP;
	R0 = R0 >>> 2 || R4 = [P3 + 32] || NOP;
	R2 = R2 + R0 (NS) || R3 = [P3 + 36] || NOP;
	R0 = MAX(R2, R3);
	R0 = MIN(R0, R4);
	R2 = R2 - R0 (NS);
	R2 = R2 >>> 3 || R4 = [P1 + 52] || NOP;
	R2 = R2 + R0 (NS) || R3 = [P1 + 56] || NOP;
	R2 = MAX(R2, R3);
	R2 = MIN(R2, R4);
.Lfr_e:
	MNOP || W[P0++] = R2 || NOP;
	[P1 + K_RNG] = R7;
	[P1 + K_LPDC] = R6;
	[P1 + K_B1CH] = R5;
	R0 = I2;
	[P1 + K_W] = R0;
	R0 = 0;
	L0 = R0;
	L1 = R0;
	L2 = R0;
	(R7:4, P5:3) = [SP++];
	RTS;
	.size _rd_k_fr, .-_rd_k_fr

	.balign 32
	.global _rd_k_r
	.type _rd_k_r, STT_FUNC
/* rd_k_r(k, count): F 0 A 1 R 1 S 0 L 0 Z 0 (body()); 108 packets a sample */
_rd_k_r:
