	B1 = R0;
	B2 = R0;
	R1 = 8192;
	L0 = R1;
	L1 = R1;
	L2 = R1;
	R0 = [P1 + K_PA];
	I0 = R0;
	R0 = [P1 + K_PB];
	I1 = R0;
	R0 = [P1 + K_W];
	I2 = R0;
	P0 = [P1 + K_OUT];
