	MNOP || R1.L = W[I0] || NOP;
	MNOP || R0.H = W[I1++] || NOP;
	MNOP || R1.H = W[I1] || NOP;
	MNOP || R3 = [P1 + 4] || NOP;
	A1 = R1.H * R2.H, A0 = R1.L * R2.L;
	A1 += R0.H * R3.H, A0 += R0.L * R3.L;
	R0.H = (A1 += R1.H * R4.H), R0.L = (A0 += R1.L * R4.L) (T) || R2 = [P1 + 12] || NOP;
