	R2 *= R3;
	R2 = R2 >>> 15;
	R1 = R1 + R2 (NS);
	R2 = R0 - R1 (NS) || R3 = [P3 + 44] || NOP;
	R2 *= R3;
	R2 = R2 >>> 15 || [P4 + 8] = R1 || NOP;
