	R0 = R0 >>> 15 || R3 = [P3 + 16] || NOP;
	R0 *= R3;
	R0 = R0 >>> 14 || R3 = [P3 + 20] || NOP;
	R0 *= R3;
	R0 = R0 >>> 15 || R3 = [P3 + 24] || NOP;
	MNOP || R4 = [P3 + 28] || NOP;
	R0 = MIN(R0, R3);
	R0 = MAX(R0, R4);
