	[P1 + K_LPDC] = R6;
	[P1 + K_B1CH] = R5;
	R0 = I2;
	[P1 + K_W] = R0;
	R0 = 0;
	L0 = R0;
	L1 = R0;
	L2 = R0;
	(R7:4, P5:3) = [SP++];
	RTS;
